function [u, store, n, same, next] = chosen(k, h)
%CHOSEN  Choices compared, chosen, numbered, held in a record.
%   k: Device (passed a choice, as its option's number)
%   h: real[N m s] (passed in m^2 kg/s)
%   returns u: Unit (passed rec)
%   returns store: real[N m s] (passed in m^2 kg/s)
%   returns n: int (passed a whole number)
%   returns same: bool (passed true or false)
%   returns next: Device (passed a choice, as its option's number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    u = asils.pcselftest.selftest.Unit_zero();
    store = 0;
    n = 0;
    same = false;
    next = 0;
    u.kind = asils.pc.choose((h > 0), 1, k);
    u.h = h;
    store = asils.pc.choose(((k == 0) || (k == 3)), (2 * h), h);
    n = (fix(u.kind) + (10 * fix(k)));
    same = (u.kind == k);
    next = asils.pc.choose((k == 3), 0, 2);
end
